#[derive(Debug, Clone, Copy)]
enum State {
    /// Between tokens: a timestamp, a pair's key or a word comes next.
    Field,
    /// Right after a key and its `=`: the value comes next.
    Value,
    /// A token was malformed; nothing more is yielded.
    Failed,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Field }
    }

    fn bytes(&self) -> &'a [u8] {
        self.src.as_bytes()
    }

    /// Reads the next timestamp, key or word; `None` when only separators remain.
    fn next_field(&mut self) -> Option<Result<Token<'a>, LexError>> {
        let bytes = self.bytes();
        let start = skip_separators(bytes, self.pos);
        self.pos = start;
        let first = *bytes.get(start)?;
        Some(match first {
            b'[' => self.timestamp(start),
            b'"' => Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => Err(LexError::EmptyKey { pos: start }),
            _ => self.key_or_word(start),
        })
    }

    /// Reads the value after a key: an empty, quoted or bare one.
    fn next_value(&mut self) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let start = self.pos;
        self.state = State::Field;
        match bytes.get(start) {
            None => Ok(Token::Bare("")),
            Some(&byte) if is_separator(byte) => Ok(Token::Bare("")),
            Some(b'"') => self.quoted(start),
            Some(_) => self.bare(start),
        }
    }

    /// `open` is the offset of the `[`.
    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let text_start = open + 1;
        let mut close = text_start;
        loop {
            match bytes.get(close) {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
                Some(_) => close += 1,
            }
        }
        self.finish(text_start, close, Token::Timestamp)
    }

    /// Reads up to the next separator; a following `=` makes it a key, otherwise it is a word.
    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let mut end = start;
        while let Some(&byte) = bytes.get(end) {
            match byte {
                b' ' | b'\\t' | b'=' => break,
                b'"' => return Err(LexError::UnexpectedQuote { pos: end }),
                _ => end += 1,
            }
        }
        let text = &self.src[start..end];
        if bytes.get(end) == Some(&b'=') {
            self.state = State::Value;
            self.pos = end + 1;
            Ok(Token::Key(text))
        } else {
            self.pos = end;
            Ok(Token::Word(text))
        }
    }

    /// `open` is the offset of the opening `"`.
    fn quoted(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let text_start = open + 1;
        let mut close = text_start;
        loop {
            match bytes.get(close) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"') => break,
                Some(b'\\\\') => match bytes.get(close + 1) {
                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\\\' | b'n' | b't') => close += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: close }),
                },
                Some(_) => close += 1,
            }
        }
        self.finish(text_start, close, Token::Quoted)
    }

    fn bare(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let mut end = start;
        while let Some(&byte) = bytes.get(end) {
            if is_separator(byte) {
                break;
            }
            if byte == b'"' {
                return Err(LexError::UnexpectedQuote { pos: end });
            }
            end += 1;
        }
        self.pos = end;
        Ok(Token::Bare(&self.src[start..end]))
    }

    /// Ends a delimited token whose text is `text_start..close` and whose closing delimiter is at `close`.
    fn finish(
        &mut self,
        text_start: usize,
        close: usize,
        token: fn(&'a str) -> Token<'a>,
    ) -> Result<Token<'a>, LexError> {
        let after = close + 1;
        if let Some(&byte) = self.bytes().get(after) {
            if !is_separator(byte) {
                return Err(LexError::ExpectedSeparator { pos: after });
            }
        }
        self.pos = after;
        Ok(token(&self.src[text_start..close]))
    }
}

fn is_separator(byte: u8) -> bool {
    byte == b' ' || byte == b'\\t'
}

fn skip_separators(bytes: &[u8], from: usize) -> usize {
    let mut pos = from;
    while bytes.get(pos).is_some_and(|&byte| is_separator(byte)) {
        pos += 1;
    }
    pos
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let item = match self.state {
            State::Field => self.next_field(),
            State::Value => Some(self.next_value()),
            State::Failed => None,
        };
        if matches!(item, Some(Err(_))) {
            self.state = State::Failed;
            self.pos = self.src.len();
        }
        item
    }
}
