            count += 1;
            let mut k = 0;
            while k < len { buf[k] += 1; if buf[k] < alpha.len() { break; } buf[k] = 0; k += 1; }
            if k == len { break; }
        }
    }
    let mut x = 0x9E3779B97F4A7C15u64;
    for _ in 0..300_000 {
        let mut s = String::new();
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
