        assert_eq!(run_new(&s), run_old(&s), "input {s:?}");
        count += 1;
    }
    println!("identical on {count} inputs");

    let lines: Vec<String> = (0..200_000).map(|i| format!("[2024-05-01T12:00:{:02}Z] level=info msg=\"disk {}% full \\\"x\\\"\" user=ann retries= done id={}", i % 60, i % 100, i)).collect();
    for round in 0..3 {
        let t = Instant::now(); let mut n = 0usize;
        for _ in 0..10 { for l in &lines { for t in tokenize(l) { n += t.is_ok() as usize; } } }
        let a = t.elapsed();
        let t = Instant::now(); let mut m = 0usize;
        for _ in 0..10 { for l in &lines { for t in old::tokenize(l) { m += t.is_ok() as usize; } } }
        let b = t.elapsed();
        println!("round {round}: new {a:?} old {b:?} ({n} {m} tokens)");
    }
}
