pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Field }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let step = match self.state {
            State::Field => read_field(self.src, self.pos)?,
            State::Value => read_value(self.src, self.pos),
            State::Failed => return None,
        };
        match step {
            Ok((token, next_pos)) => {
                self.pos = next_pos;
                self.state = if matches!(token, Token::Key(_)) { State::Value } else { State::Field };
                Some(Ok(token))
            }
            Err(error) => {
                self.pos = self.src.len();
                self.state = State::Failed;
                Some(Err(error))
            }
        }
    }
}

/// A token and the offset where reading continues.
type Step<'a> = Result<(Token<'a>, usize), LexError>;

/// Reads a timestamp, key or word at or after `pos`; `None` when only separators remain.
fn read_field(src: &str, pos: usize) -> Option<Step<'_>> {
    let bytes = src.as_bytes();
    let start = skip_separators(bytes, pos);
    let step = match *bytes.get(start)? {
        b'[' => read_timestamp(src, start),
        b'"' => Err(LexError::UnexpectedQuote { pos: start }),
        b'=' => Err(LexError::EmptyKey { pos: start }),
        _ => read_key_or_word(src, start),
    };
    Some(step)
}

/// Reads the value that follows a key: a quoted one, a bare one, or an empty one.
fn read_value(src: &str, start: usize) -> Step<'_> {
    match src.as_bytes().get(start) {
        Some(b'"') => read_quoted(src, start),
        Some(&byte) if !is_separator(byte) => read_bare(src, start),
        _ => Ok((Token::Bare(""), start)),
    }
}

/// `open` is the offset of the `[`.
fn read_timestamp(src: &str, open: usize) -> Step<'_> {
    let bytes = src.as_bytes();
    let text_start = open + 1;
    let mut close = text_start;
    loop {
        match bytes.get(close) {
            None => return Err(LexError::UnterminatedTimestamp { pos: open }),
            Some(b']') => break,
            Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
            Some(_) => close += 1,
        }
    }
    let next_pos = after_closing_delimiter(bytes, close)?;
    Ok((Token::Timestamp(&src[text_start..close]), next_pos))
}

/// Reads up to the next separator; a `=` right after the text makes it a key, otherwise it is a word.
fn read_key_or_word(src: &str, start: usize) -> Step<'_> {
    let bytes = src.as_bytes();
    let mut end = start;
    while let Some(&byte) = bytes.get(end) {
        match byte {
            b' ' | b'\t' | b'=' => break,
            b'"' => return Err(LexError::UnexpectedQuote { pos: end }),
            _ => end += 1,
        }
    }
    let text = &src[start..end];
    if bytes.get(end) == Some(&b'=') {
        Ok((Token::Key(text), end + 1))
    } else {
        Ok((Token::Word(text), end))
    }
}

/// `open` is the offset of the opening `"`.
fn read_quoted(src: &str, open: usize) -> Step<'_> {
    let bytes = src.as_bytes();
    let text_start = open + 1;
    let mut close = text_start;
    loop {
        match bytes.get(close) {
            None => return Err(LexError::UnterminatedQuote { pos: open }),
            Some(b'"') => break,
            Some(b'\\') => match bytes.get(close + 1) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"' | b'\\' | b'n' | b't') => close += 2,
                Some(_) => return Err(LexError::InvalidEscape { pos: close }),
            },
            Some(_) => close += 1,
        }
    }
    let next_pos = after_closing_delimiter(bytes, close)?;
    Ok((Token::Quoted(&src[text_start..close]), next_pos))
}

fn read_bare(src: &str, start: usize) -> Step<'_> {
    let bytes = src.as_bytes();
    let mut end = start;
    while let Some(&byte) = bytes.get(end) {
        if is_separator(byte) {
            break;
        }
        if byte == b'"' {
            return Err(LexError::UnexpectedQuote { pos: end });
        }
        end += 1;
    }
    Ok((Token::Bare(&src[start..end]), end))
}

