mod error { include!("../src/error.rs"); }
mod new { include!("../src/token.rs"); }
mod old { include!("../../oracle/old_token.rs"); }

fn run_new(s: &str) -> Vec<String> {
    let mut it = new::tokenize(s);
    (0..40).map(|_| format!("{:?}", it.next())).collect()
}
fn run_old(s: &str) -> Vec<String> {
    let mut it = old::tokenize(s);
    (0..40).map(|_| format!("{:?}", it.next())).collect()
}

fn main() {
    let alpha: Vec<&str> = vec!["[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "é"];
    let mut count = 0u64;
    for len in 0..=7 {
        let mut buf = vec![0usize; len];
        loop {
            let s: String = buf.iter().map(|&i| alpha[i]).collect();
            assert_eq!(run_new(&s), run_old(&s), "input {s:?}");
            count += 1;
            let mut k = 0;
            while k < len {
                buf[k] += 1;
                if buf[k] < alpha.len() { break; }
                buf[k] = 0;
                k += 1;
            }
            if k == len { break; }
        }
    }
    let mut x = 0x9E3779B97F4A7C15u64;
    for _ in 0..300_000 {
        let mut s = String::new();
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        let len = (x % 40) as usize;
        for _ in 0..len {
            x ^= x << 13; x ^= x >> 7; x ^= x << 17;
            s.push_str(alpha[(x % alpha.len() as u64) as usize]);
        }
        assert_eq!(run_new(&s), run_old(&s), "input {s:?}");
        count += 1;
    }
    println!("identical (tokens, errors, and end-of-stream) on {count} inputs");
}

