use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Where the tokenizer is within a line.
#[derive(Debug, Clone, Copy)]
enum State {
    /// Between tokens: a timestamp, a pair's key or a word comes next.
    Field,
    /// Right after a key and its `=`: the value comes next.
    Value,
    /// A token was malformed; nothing more is yielded.
    Failed,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Field }
    }

    /// Reads a timestamp, key or word; `Ok(None)` when only separators remain.
    fn read_field(&mut self) -> Result<Option<Token<'a>>, LexError> {
        let src = self.src;
        let bytes = src.as_bytes();
        let start = skip_separators(bytes, self.pos);
        let token = match bytes.get(start) {
            None => return Ok(None),
            Some(b'[') => {
                let close = scan_timestamp(bytes, start)?;
                self.pos = close + 1;
                Token::Timestamp(&src[start + 1..close])
            }
            Some(b'"') => return Err(LexError::UnexpectedQuote { pos: start }),
            Some(b'=') => return Err(LexError::EmptyKey { pos: start }),
            Some(_) => {
                let end = scan_name(bytes, start)?;
                if bytes.get(end) == Some(&b'=') {
                    self.state = State::Value;
                    self.pos = end + 1;
                    Token::Key(&src[start..end])
                } else {
                    self.pos = end;
                    Token::Word(&src[start..end])
                }
            }
        };
        Ok(Some(token))
    }

    /// Reads the value after a key: quoted, bare, or empty.
    fn read_value(&mut self) -> Result<Token<'a>, LexError> {
        let src = self.src;
        let bytes = src.as_bytes();
        let start = self.pos;
        self.state = State::Field;
        match bytes.get(start) {
            Some(b'"') => {
                let close = scan_quoted(bytes, start)?;
                self.pos = close + 1;
                Ok(Token::Quoted(&src[start + 1..close]))
            }
            Some(&byte) if !is_separator(byte) => {
                let end = scan_bare(bytes, start)?;
                self.pos = end;
                Ok(Token::Bare(&src[start..end]))
            }
            _ => Ok(Token::Bare("")),
        }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        match self.state {
            State::Field => match self.read_field() {
                Ok(Some(token)) => Some(Ok(token)),
                Ok(None) => None,
                Err(error) => Some(Err(self.fail(error))),
            },
            State::Value => Some(self.read_value().map_err(|error| self.fail(error))),
            State::Failed => None,
        }
    }
}

impl Tokens<'_> {
    /// Ends the token stream; the rest of the line is not read.
    #[cold]
    fn fail(&mut self, error: LexError) -> LexError {
        self.state = State::Failed;
        self.pos = self.src.len();
        error
    }
}

/// Offset of the `]` that closes the timestamp opened at `open`; a separator or the line's end must follow it.
#[inline(always)]
fn scan_timestamp(bytes: &[u8], open: usize) -> Result<usize, LexError> {
    let mut close = open + 1;
    loop {
        match bytes.get(close) {
            None => return Err(LexError::UnterminatedTimestamp { pos: open }),
            Some(b']') => break,
            Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
            Some(_) => close += 1,
        }
    }
    expect_separator_after(bytes, close)?;
    Ok(close)
}

/// End offset of the text that starts at `start` and runs up to a separator or a `=`.
#[inline(always)]
fn scan_name(bytes: &[u8], start: usize) -> Result<usize, LexError> {
    let mut end = start;
    while let Some(&byte) = bytes.get(end) {
        if is_separator(byte) || byte == b'=' {
            break;
        }
        if byte == b'"' {
            return Err(LexError::UnexpectedQuote { pos: end });
        }
        end += 1;
    }
    Ok(end)
}

/// Offset of the `"` that closes the quoted value opened at `open`; a separator or the line's end must follow it.
#[inline(always)]
fn scan_quoted(bytes: &[u8], open: usize) -> Result<usize, LexError> {
    let mut close = open + 1;
    loop {
        match bytes.get(close) {
            None => return Err(LexError::UnterminatedQuote { pos: open }),
            Some(b'"') => break,
            Some(b'\\') => match bytes.get(close + 1) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"' | b'\\' | b'n' | b't') => close += 2,
                Some(_) => return Err(LexError::InvalidEscape { pos: close }),
            },
            Some(_) => close += 1,
        }
    }
    expect_separator_after(bytes, close)?;
    Ok(close)
}

/// End offset of the unquoted value that starts at `start`.
#[inline(always)]
fn scan_bare(bytes: &[u8], start: usize) -> Result<usize, LexError> {
    let mut end = start;
    while let Some(&byte) = bytes.get(end) {
        if is_separator(byte) {
            break;
        }
        if byte == b'"' {
            return Err(LexError::UnexpectedQuote { pos: end });
        }
        end += 1;
    }
    Ok(end)
}

#[inline(always)]
fn expect_separator_after(bytes: &[u8], close: usize) -> Result<(), LexError> {
    let after = close + 1;
    match bytes.get(after) {
        Some(&byte) if !is_separator(byte) => Err(LexError::ExpectedSeparator { pos: after }),
        _ => Ok(()),
    }
}

#[inline(always)]
fn is_separator(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

#[inline(always)]
fn skip_separators(bytes: &[u8], from: usize) -> usize {
    let mut pos = from;
    while bytes.get(pos).is_some_and(|&byte| is_separator(byte)) {
        pos += 1;
    }
    pos
}
